use std::{fs::{self,File},io::{self,Read,Write},path::{Path,PathBuf}};
use flate2::{read::GzDecoder,write::GzEncoder,Compression};
use walkdir::WalkDir;
use zip::{ZipArchive,ZipWriter,write::SimpleFileOptions};
fn safe_name(path:&Path)->String{path.components().filter_map(|c|match c{std::path::Component::Normal(s)=>Some(s.to_string_lossy().to_string()),_=>None}).collect::<Vec<_>>().join("/")}
fn entries(inputs:&[PathBuf])->Result<Vec<(PathBuf,String,u64)>,String>{let mut v=Vec::new();for input in inputs{let base=if input.is_dir(){input.parent().unwrap_or(input)}else{input.parent().unwrap_or(Path::new("."))};if input.is_file(){v.push((input.clone(),safe_name(input.strip_prefix(base).unwrap_or(input)),input.metadata().map_err(|e|e.to_string())?.len()));}else{for e in WalkDir::new(input).follow_links(false){let e=e.map_err(|e|e.to_string())?;if e.file_type().is_file(){let p=e.path().to_path_buf();let n=p.metadata().map_err(|e|e.to_string())?.len();v.push((p.clone(),safe_name(p.strip_prefix(base).map_err(|e|e.to_string())?),n));}}}}Ok(v)}
pub fn create<F:FnMut(u64,u64)>(inputs:&[PathBuf],out:&Path,fmt:&str,level:u32,mut progress:F)->Result<(u64,u64),String>{if inputs.is_empty(){return Err("Немає файлів для архівування".into())}if out.exists(){return Err("Файл призначення вже існує".into())}let files=entries(inputs)?;let total=files.iter().map(|x|x.2).sum::<u64>();let mut done=0u64;let result:Result<(),String>=match fmt{"zip"=>{let f=File::create(out).map_err(|e|e.to_string())?;let mut z=ZipWriter::new(f);let opt=SimpleFileOptions::default().compression_method(zip::CompressionMethod::Deflated).compression_level(Some(level as i64));let mut buf=[0u8;1024*1024];for(p,name,size)in &files{z.start_file(name,opt).map_err(|e|e.to_string())?;let mut f=File::open(p).map_err(|e|e.to_string())?;loop{let n=f.read(&mut buf).map_err(|e|e.to_string())?;if n==0{break}z.write_all(&buf[..n]).map_err(|e|e.to_string())?;done+=n as u64;progress(done,total);}}z.finish().map_err(|e|e.to_string())?;Ok(())},"tar"|"tar.gz"=>{let f=File::create(out).map_err(|e|e.to_string())?;let writer:Box<dyn Write>=if fmt=="tar.gz"{Box::new(GzEncoder::new(f,Compression::new(level)))}else{Box::new(f)};let mut t=tar::Builder::new(writer);let mut buf=[0u8;1024*1024];for(p,name,_)in &files{let mut f=File::open(p).map_err(|e|e.to_string())?;let mut h=tar::Header::new_gnu();h.set_path(name).map_err(|e|e.to_string())?;h.set_size(f.metadata().map_err(|e|e.to_string())?.len());h.set_mode(0o644);h.set_cksum();t.append(&h,&mut f).map_err(|e|e.to_string())?;done+=f.metadata().map_err(|e|e.to_string())?.len();progress(done,total);}t.finish().map_err(|e|e.to_string())?;Ok(())},_=>Err("Непідтримуваний формат".into())};result?;let output=out.metadata().map_err(|e|e.to_string())?.len();Ok((total,output))}
pub fn extract(src:&Path,dest:&Path)->Result<u64,String>{fs::create_dir_all(dest).map_err(|e|e.to_string())?;let ext=src.extension().and_then(|s|s.to_str()).unwrap_or("").to_ascii_lowercase();if ext=="zip"{let f=File::open(src).map_err(|e|e.to_string())?;let mut z=ZipArchive::new(f).map_err(|e|e.to_string())?;let mut total=0;for i in 0..z.len(){let mut file=z.by_index(i).map_err(|e|e.to_string())?;let Some(rel)=file.enclosed_name().map(|p|p.to_owned())else{continue};let out=dest.join(rel);if file.is_dir(){fs::create_dir_all(&out).map_err(|e|e.to_string())?;}else{if let Some(p)=out.parent(){fs::create_dir_all(p).map_err(|e|e.to_string())?;}let mut o=File::create(out).map_err(|e|e.to_string())?;total+=io::copy(&mut file,&mut o).map_err(|e|e.to_string())?;}}Ok(total)}else if src.to_string_lossy().to_ascii_lowercase().ends_with(".tar.gz")||ext=="tgz"{let f=File::open(src).map_err(|e|e.to_string())?;let mut a=tar::Archive::new(GzDecoder::new(f));a.unpack(dest).map_err(|e|e.to_string())?;Ok(0)}else if ext=="tar"{let f=File::open(src).map_err(|e|e.to_string())?;let mut a=tar::Archive::new(f);a.unpack(dest).map_err(|e|e.to_string())?;Ok(0)}else{Err("Підтримуються ZIP, TAR і TAR.GZ".into())}}
